#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define MAX_ENTRIES 64
#define ENTRY_SIZE 256
#define SHM_SIZE 4096

typedef struct {
    volatile int entry_count;
    char entries[MAX_ENTRIES][ENTRY_SIZE];
} shared_log_t;

typedef struct {
    char username[64];
    int privilege_level;
    int max_readable_entries;
} user_context_t;

static shared_log_t *g_shared_log = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

int init_shared_log(void) {
    g_shared_log = mmap(NULL, SHM_SIZE, PROT_READ | PROT_WRITE,
                        MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (g_shared_log == MAP_FAILED) {
        perror("mmap");
        return -1;
    }
    g_shared_log->entry_count = 0;
    return 0;
}

int add_log_entry(const char *message) {
    if (!message) return -1;
    pthread_mutex_lock(&log_mutex);
    if (g_shared_log->entry_count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }
    strncpy(g_shared_log->entries[g_shared_log->entry_count], message, ENTRY_SIZE - 1);
    g_shared_log->entries[g_shared_log->entry_count][ENTRY_SIZE - 1] = '\0';
    g_shared_log->entry_count++;
    pthread_mutex_unlock(&log_mutex);
    return 0;
}

/* Validates that the requested index is within bounds */
static int validate_access(const user_context_t *user, int requested_idx, int current_count) {
    if (requested_idx < 0) return -1;
    if (requested_idx >= current_count) return -1;
    if (requested_idx >= user->max_readable_entries) return -1;
    return 0;
}

/* Read a specific log entry with access control */
int read_log_entry(const user_context_t *user, int idx, char *out_buf, size_t out_len) {
    if (!user || !out_buf || out_len == 0) return -1;
    if (out_len > ENTRY_SIZE) out_len = ENTRY_SIZE;

    pthread_mutex_lock(&log_mutex);
    int current_count = g_shared_log->entry_count;

    /* Validate access permissions using snapshotted count */
    if (validate_access(user, idx, current_count) != 0) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    /* Copy the entry to output buffer while holding lock */
    memcpy(out_buf, g_shared_log->entries[idx], out_len);
    out_buf[out_len - 1] = '\0';
    pthread_mutex_unlock(&log_mutex);
    return 0;
}

/* Dump all accessible entries for a user */
int dump_user_logs(const user_context_t *user, char *out_buf, size_t out_len) {
    if (!user || !out_buf || out_len == 0) return -1;

    pthread_mutex_lock(&log_mutex);
    size_t offset = 0;
    int count = g_shared_log->entry_count;

    /* Bound by user permissions */
    if (count > user->max_readable_entries)
        count = user->max_readable_entries;
    if (count > MAX_ENTRIES)
        count = MAX_ENTRIES;

    for (int i = 0; i < count; i++) {
        size_t remaining = out_len - offset;
        if (remaining <= 1) break;
        int written = snprintf(out_buf + offset, remaining, "[%d] %s\n",
                              i, g_shared_log->entries[i]);
        if (written > 0 && (size_t)written < remaining)
            offset += written;
        else
            break;
    }
    pthread_mutex_unlock(&log_mutex);
    return (int)offset;
}

/* Get total count of entries - used for pagination */
int get_entry_count(void) {
    pthread_mutex_lock(&log_mutex);
    int count = g_shared_log->entry_count;
    pthread_mutex_unlock(&log_mutex);
    return count;
}

/* Retrieve entries in a range with bounds checking */
int read_entry_range(const user_context_t *user, int start, int end,
                     char *out_buf, size_t out_len) {
    if (!user || !out_buf || out_len == 0) return -1;
    if (start < 0 || end < start) return -1;

    pthread_mutex_lock(&log_mutex);

    int current_count = g_shared_log->entry_count;

    /* Check that end doesn't exceed available entries */
    if (end > current_count) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    /* Check user permissions */
    if (end > user->max_readable_entries) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    /* Validated - now copy entries while still holding lock */
    size_t offset = 0;
    for (int i = start; i < end; i++) {
        size_t remaining = out_len - offset;
        if (remaining <= 1) break;
        int written = snprintf(out_buf + offset, remaining, "%s\n",
                              g_shared_log->entries[i]);
        if (written > 0 && (size_t)written < remaining)
            offset += written;
        else
            break;
    }
    pthread_mutex_unlock(&log_mutex);
    return (int)offset;
}

void cleanup_shared_log(void) {
    if (g_shared_log && g_shared_log != MAP_FAILED) {
        munmap(g_shared_log, SHM_SIZE);
        g_shared_log = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (init_shared_log() != 0) return 1;

    add_log_entry("System started");
    add_log_entry("User admin logged in");
    add_log_entry("Configuration loaded");
    add_log_entry("SECRET: database_password=hunter2");
    add_log_entry("SECRET: api_key=sk-12345abcdef");

    user_context_t regular_user = {
        .username = "guest",
        .privilege_level = 1,
        .max_readable_entries = 3
    };

    char buffer[2048];
    memset(buffer, 0, sizeof(buffer));

    /* This should only show first 3 entries */
    int result = dump_user_logs(&regular_user, buffer, sizeof(buffer));
    if (result > 0) {
        printf("User logs:\n%s\n", buffer);
    }

    /* Range read test */
    memset(buffer, 0, sizeof(buffer));
    result = read_entry_range(&regular_user, 0, 2, buffer, sizeof(buffer));
    if (result > 0) {
        printf("Range [0,2):\n%s\n", buffer);
    }

    cleanup_shared_log();
    return 0;
}
